def find_insert_position(sorted_values, target):
    """Return the index where target should be inserted to keep the list sorted.

    If target is already present, return the index of its FIRST occurrence.
    """
    low = 0
    high = len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	// Start a goroutine to close the jobs channel once all inputs are sent.
	// This prevents the main goroutine from blocking on wg.Wait() while
	// the workers are waiting for more jobs or for the channel to close.
	go func() {
		for i := range inputs {
			jobs <- i
		}
		close(jobs)
	}()

	wg.Wait()
	return out
}

package cache

import (
	"container/list"
	"sync"
)

// entry holds the key and value stored in the list nodes.
type entry struct {
	key   string
	value int
}

// LRU implements a fixed-capacity least recently used cache.
type LRU struct {
	capacity int
	mu       sync.Mutex
	ll       *list.List
	cache    map[string]*list.Element
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity: capacity,
		ll:       list.New(),
		cache:    make(map[string]*list.Element),
	}
}

// Get returns the value associated with the key and true if found,
// otherwise returns 0 and false. It moves the accessed element to the front.
func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if ele, ok := c.cache[key]; ok {
		c.ll.MoveToFront(ele)
		return ele.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds a value to the cache. If the key exists, it updates the value.
// If the cache is at capacity and a new key is added, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	// If key exists, update value and move to front
	if ele, ok := c.cache[key]; ok {
		c.ll.MoveToFront(ele)
		ele.Value.(*entry).value = value
		return
	}

	// If at capacity, evict the oldest
	if c.ll.Len() >= c.capacity && c.capacity > 0 {
		oldest := c.ll.Back()
		if oldest != nil {
			c.ll.Remove(oldest)
			kv := oldest.Value.(*entry)
			delete(c.cache, kv.key)
		}
	}

	// If capacity is 0, do nothing
	if c.capacity <= 0 {
		return
	}

	// Add new entry
	ele := c.ll.PushFront(&entry{key, value})
	c.cache[key] = ele
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.ll.Len()
}

export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) {
    return [];
  }

  const result: number[][] = [];
  let currentRun: number[] = [values[0]];

  for (let i = 1; i < values.length; i++) {
    const current = values[i];
    const previous = values[i - 1];

    if (current === previous + 1) {
      currentRun.push(current);
    } else {
      result.push(currentRun);
      currentRun = [current];
    }
  }

  result.push(currentRun);
  return result;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Rewrite this to use async/await and a plain loop. Behaviour must not change,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let currentId: string | null = start;

  while (currentId !== null) {
    if (seen.has(currentId)) {
      throw new Error("cycle detected");
    }
    seen.add(currentId);
    chain.push(currentId);

    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(currentId);
    currentId = node.parent;
  }

  return chain;
}

